    "research.athanor-autonomous-post-training.title": "Athanor: Autonomous post-training research by AI agents",
    "research.athanor-autonomous-post-training.summary": "This preprint describes autonomous post-training on real GPUs, with frozen evaluation, job management and research records. Results are specific to its models and experimental setup, rather than evidence of general autonomous science.",
    "research.into-the-unknown-agent-benchmark.title": "Into the Unknown: Evaluating agents on open scientific problems",
    "research.into-the-unknown-agent-benchmark.summary": "This preprint uses scientists’ unpublished research directions for evaluation. None of 135 follow-up papers generated by nine agents meets every condition, highlighting limits in research integrity and verification.",
    "research.nist-curve-seed-origins.title": "Tracing the origins of NIST elliptic-curve seeds",
    "research.nist-curve-seed-origins.summary": "Anthropic publishes code linking five NIST prime-curve seeds to lrand48 and historical timestamps. This does not break ECDSA; some base points and candidate-selection rules remain unexplained.",
    "research.count": "Research: {count}",
